        raise ValueError("Length of num_str does not match N")
    if K < 0:
        raise ValueError("K must be non‑negative")
    # It's impossible to place more than N-1 signs
    if K > N - 1:
        return 0

    from functools import lru_cache

    @lru_cache(None)
    def dp(i: int, k: int) -> int:
        """
        Returns the maximum product for the prefix num_str[:i] using k multiplication signs,
        i.e., split into k+1 parts.
        """
        if k == 0:
            return int(num_str[:i]) if i > 0 else 0
        res = 0
        # Each part must contain at least one digit, so j must be at least k
        for j in range(k, i):
            left = dp(j, k - 1)
            right = int(num_str[j:i])
            prod = left * right
            if prod > res:
                res = prod
        return res

    return dp(N, K)

